#!/usr/bin/env python3
"""Generate the Global Smartwatch Secondary Market Analysis Q1 2026 report."""

import pandas as pd
import numpy as np
import json
import os

# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
main_brands = ['Apple', 'Garmin', 'Samsung']
df_main = df[df['brand'].isin(main_brands)].copy()

# ── Normalize conditions (handle non-English labels) ───────────────────────
cond_map = {}
for c in df_main['condition'].unique():
    cl = str(c).lower()
    if 'new' in cl or 'nuevo' in cl or 'novo' in cl:
        cond_map[c] = 'New'
    elif 'used' in cl or 'usado' in cl:
        cond_map[c] = 'Used'
    elif 'open box' in cl or 'caja abierta' in cl:
        cond_map[c] = 'Open Box'
    elif 'refurbished' in cl:
        cond_map[c] = 'Refurbished'
    elif 'parts' in cl or 'not working' in cl:
        cond_map[c] = 'For Parts'
    else:
        cond_map[c] = c
df_main['cond_norm'] = df_main['condition'].map(cond_map)

# ── KPIs ───────────────────────────────────────────────────────────────────
kpi_brand_median = {}
for b in main_brands:
    kpi_brand_median[b] = round(df_main[df_main['brand'] == b]['price'].median(), 2)

# Geographic price spread
geo_spreads = {}
for b in main_brands:
    sub = df_main[df_main['brand'] == b]
    cm = sub.groupby('Country')['price'].agg(['median', 'count'])
    cm = cm[cm['count'] >= 5]
    if len(cm) > 1:
        geo_spreads[b] = {
            'spread': round(cm['median'].max() - cm['median'].min(), 2),
            'high': cm['median'].idxmax(),
            'high_val': round(cm['median'].max(), 2),
            'low': cm['median'].idxmin(),
            'low_val': round(cm['median'].min(), 2),
        }

# Case size correlation
valid_cs = df_main[df_main['Case_Size_mm'].notna()]
cs_corr = round(np.corrcoef(valid_cs['Case_Size_mm'].values, valid_cs['price'].values)[0, 1], 4)

# Power seller concentration
seller_counts = df_main['Seller_ID'].value_counts()
n_top5pct = max(1, int(len(seller_counts) * 0.05))
top_sellers = seller_counts.head(n_top5pct)
concentration_pct = round(top_sellers.sum() / len(df_main) * 100, 1)

# New vs Used price premium
new_used_premium = {}
for b in main_brands:
    sub = df_main[df_main['brand'] == b]
    new_avg = sub[sub['condition'] == 'New']['price'].mean()
    used_avg = sub[sub['condition'] == 'Used']['price'].mean()
    if used_avg > 0:
        new_used_premium[b] = round((new_avg - used_avg) / used_avg * 100, 1)

# ── Chart data helpers ─────────────────────────────────────────────────────
def chart_data_brand_pricing():
    """Box plot data for brand pricing."""
    datasets = []
    colors = {'Apple': 'rgba(102, 102, 102, 0.7)', 'Garmin': 'rgba(0, 163, 224, 0.7)', 'Samsung': 'rgba(20, 40, 120, 0.7)'}
    for b in main_brands:
        prices = df_main[df_main['brand'] == b]['price'].dropna().values.tolist()
        datasets.append({'label': b, 'data': prices, 'backgroundColor': colors[b]})
    return json.dumps(datasets)

def chart_data_brand_stats():
    """Mean/median/min/max for brand pricing."""
    result = []
    for b in main_brands:
        sub = df_main[df_main['brand'] == b]
        result.append({
            'brand': b,
            'mean': round(sub['price'].mean(), 2),
            'median': round(sub['price'].median(), 2),
            'p25': round(sub['price'].quantile(0.25), 2),
            'p75': round(sub['price'].quantile(0.75), 2),
            'min': round(sub['price'].min(), 2),
            'max': round(sub['price'].max(), 2),
        })
    return json.dumps(result)

def chart_data_geo_heatmap():
    """Country-level median prices by brand for heatmap/diverging bar."""
    result = {}
    for b in main_brands:
        sub = df_main[df_main['brand'] == b]
        cm = sub.groupby('Country')['price'].agg(['median', 'count'])
        cm = cm[cm['count'] >= 3].sort_values('median', ascending=False)
        result[b] = [{'country': idx, 'median': round(row['median'], 2), 'count': int(row['count'])} for idx, row in cm.iterrows()]
    return json.dumps(result)

def chart_data_case_size():
    """Case size bin data by brand."""
    bins = [0, 40, 43, 46, 49, 100]
    labels = ['<40mm', '40-43mm', '44-46mm', '47-49mm', '50mm+']
    result = []
    for b in main_brands:
        sub = valid_cs[valid_cs['brand'] == b].copy()
        sub['size_bin'] = pd.cut(sub['Case_Size_mm'], bins=bins, labels=labels)
        stats = sub.groupby('size_bin', observed=False)['price'].agg(['median', 'count'])
        result.append({
            'brand': b,
            'labels': labels,
            'medians': [float(round(stats.loc[l, 'median'], 2)) if l in stats.index and not pd.isna(stats.loc[l, 'median']) else None for l in labels],
            'counts': [int(stats.loc[l, 'count']) if l in stats.index else 0 for l in labels],
        })
    return json.dumps(result)

def chart_data_seller_scatter():
    """Seller volume vs median price."""
    seller_agg = df_main.groupby('Seller_ID').agg(
        listings=('price', 'count'),
        median_price=('price', 'median'),
        brand=('brand', lambda x: x.mode().iloc[0] if len(x) > 0 else 'Unknown')
    ).reset_index()
    return json.dumps(seller_agg[['listings', 'median_price', 'brand']].to_dict('records'))

def chart_data_condition_premium():
    """New vs Used prices by brand."""
    result = []
    for b in main_brands:
        sub = df_main[df_main['brand'] == b]
        for cond in ['New', 'Used', 'Open Box', 'Refurbished']:
            cs = sub[sub['cond_norm'] == cond]
            if len(cs) > 0:
                result.append({'brand': b, 'condition': cond, 'median': round(cs['price'].median(), 2), 'count': len(cs)})
    return json.dumps(result)

def chart_data_power_seller_pricing():
    """Power vs casual seller pricing by brand."""
    top_seller_ids = set(seller_counts.head(n_top5pct).index)
    df_main['seller_type'] = df_main['Seller_ID'].apply(lambda x: 'Power Seller' if x in top_seller_ids else 'Casual Seller')
    result = []
    for st in ['Power Seller', 'Casual Seller']:
        for b in main_brands:
            sub = df_main[(df_main['seller_type'] == st) & (df_main['brand'] == b)]
            if len(sub) > 0:
                result.append({'seller_type': st, 'brand': b, 'median': round(sub['price'].median(), 2), 'count': len(sub)})
    return json.dumps(result)

def chart_data_brand_distribution():
    """Brand + condition distribution for overview."""
    result = []
    for b in main_brands:
        for cond in ['New', 'Used', 'Open Box', 'Refurbished', 'For Parts']:
            cnt = len(df_main[(df_main['brand'] == b) & (df_main['cond_norm'] == cond)])
            if cnt > 0:
                result.append({'brand': b, 'condition': cond, 'count': cnt})
    return json.dumps(result)

def chart_data_country_distribution():
    """Top countries by listing volume."""
    country_counts = df_main['Country'].value_counts().head(12).reset_index()
    country_counts.columns = ['country', 'count']
    return json.dumps(country_counts.to_dict('records'))

def chart_data_shipping():
    """Worldwide shipping by brand."""
    result = []
    for b in main_brands:
        sub = df_main[df_main['brand'] == b]
        ww = int(sub['Is_Worldwide_Shipping'].sum())
        domestic = len(sub) - ww
        result.append({'brand': b, 'worldwide': ww, 'domestic': domestic})
    return json.dumps(result)

# ── Build HTML ─────────────────────────────────────────────────────────────
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Smartwatch Secondary Market Analysis — Q1 2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #f8f9fa;
    --card-bg: #fff;
    --text: #1a1a2e;
    --text-secondary: #495057;
    --border: #dee2e6;
    --accent: #0d6efd;
    --accent-green: #198754;
    --accent-orange: #fd7e14;
    --accent-red: #dc3545;
    --apple: #6c757d;
    --garmin: #0d6efd;
    --samsung: #142878;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 15px;
  }}
  .container {{ max-width: 1200px; margin: 0 auto; padding: 0 24px; }}

  /* Header */
  .report-header {{
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    color: #fff;
    padding: 60px 0 48px;
  }}
  .report-header h1 {{ font-size: 2.2rem; font-weight: 700; letter-spacing: -0.5px; margin-bottom: 12px; }}
  .report-header .subtitle {{ font-size: 1.05rem; color: rgba(255,255,255,0.8); max-width: 800px; margin-bottom: 8px; }}
  .report-header .meta {{ font-size: 0.85rem; color: rgba(255,255,255,0.55); }}

  /* KPI Cards */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-top: -32px;
    margin-bottom: 48px;
    position: relative;
    z-index: 10;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 22px 18px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
    border: 1px solid var(--border);
  }}
  .kpi-card .label {{ font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.6px; color: var(--text-secondary); margin-bottom: 6px; font-weight: 600; }}
  .kpi-card .value {{ font-size: 1.7rem; font-weight: 700; color: var(--text); margin-bottom: 4px; }}
  .kpi-card .context {{ font-size: 0.78rem; color: var(--text-secondary); }}

  /* Sections */
  .section {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 36px 32px;
    margin-bottom: 28px;
    box-shadow: 0 1px 6px rgba(0,0,0,0.04);
    border: 1px solid var(--border);
  }}
  .section h2 {{
    font-size: 1.4rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: var(--text);
    display: flex;
    align-items: center;
    gap: 10px;
  }}
  .section h2 .section-num {{
    background: var(--accent);
    color: #fff;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.85rem;
    font-weight: 700;
    flex-shrink: 0;
  }}
  .section .objective {{
    color: var(--text-secondary);
    font-size: 0.92rem;
    margin-bottom: 24px;
    padding-bottom: 20px;
    border-bottom: 1px solid var(--border);
  }}
  .section h3 {{
    font-size: 1.1rem;
    font-weight: 600;
    margin: 28px 0 12px;
    color: var(--text);
  }}

  /* Chart containers */
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 20px 0;
  }}
  .chart-row.three {{ grid-template-columns: 1fr 1fr 1fr; }}
  .chart-box {{
    background: #fafbfc;
    border-radius: 8px;
    padding: 16px;
    border: 1px solid var(--border);
  }}
  .chart-box.full {{ grid-column: 1 / -1; }}
  .chart-box h4 {{
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    color: var(--text-secondary);
    margin-bottom: 12px;
    font-weight: 600;
  }}
  .chart-box canvas {{ width: 100% !important; max-height: 340px; }}

  /* Tables */
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.88rem;
    margin: 16px 0;
  }}
  th {{ background: #f0f2f5; font-weight: 600; text-align: left; padding: 10px 14px; border-bottom: 2px solid var(--border); font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.3px; color: var(--text-secondary); }}
  td {{ padding: 10px 14px; border-bottom: 1px solid var(--border); }}
  tr:last-child td {{ border-bottom: none; }}
  .highlight {{ background: #e7f1ff; font-weight: 600; }}
  .lowlight {{ background: #fff3e0; }}

  /* Insights */
  .insight {{ background: #e7f1ff; border-left: 4px solid var(--accent); padding: 14px 18px; margin: 18px 0; border-radius: 0 8px 8px 0; font-size: 0.9rem; color: #0a3d6e; }}
  .insight strong {{ color: #052c52; }}
  .insight.green {{ background: #e8f5e9; border-left-color: var(--accent-green); color: #1b5e20; }}
  .insight.amber {{ background: #fff8e1; border-left-color: var(--accent-orange); color: #7a4a00; }}

  /* Geo grid */
  .geo-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    margin: 20px 0;
  }}
  .geo-card {{
    background: #fafbfc;
    border-radius: 8px;
    padding: 18px;
    border: 1px solid var(--border);
  }}
  .geo-card h4 {{ font-size: 0.9rem; font-weight: 700; margin-bottom: 12px; }}
  .geo-card .spread {{ font-size: 1.4rem; font-weight: 700; margin-bottom: 8px; }}
  .geo-card .detail {{ font-size: 0.82rem; color: var(--text-secondary); }}

  /* Recommendation cards */
  .rec-cards {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin: 20px 0;
  }}
  .rec-card {{
    background: #fafbfc;
    border-radius: 8px;
    padding: 20px;
    border: 1px solid var(--border);
  }}
  .rec-card .rec-num {{
    display: inline-block;
    background: var(--accent);
    color: #fff;
    width: 26px;
    height: 26px;
    border-radius: 6px;
    text-align: center;
    line-height: 26px;
    font-size: 0.8rem;
    font-weight: 700;
    margin-bottom: 8px;
  }}
  .rec-card h4 {{ font-size: 0.95rem; font-weight: 700; margin-bottom: 8px; }}
  .rec-card p {{ font-size: 0.86rem; color: var(--text-secondary); }}

  /* Footer */
  .report-footer {{
    text-align: center;
    padding: 32px 0 48px;
    color: var(--text-secondary);
    font-size: 0.82rem;
  }}

  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(3, 1fr); }}
    .chart-row, .geo-grid, .rec-cards {{ grid-template-columns: 1fr; }}
    .chart-row.three {{ grid-template-columns: 1fr; }}
  }}
</style>
</head>
<body>

<!-- Header -->
<header class="report-header">
  <div class="container">
    <h1>Global Smartwatch Secondary Market Analysis — Q1 2026</h1>
    <p class="subtitle">A comprehensive analysis of 3,586 secondary-market smartwatch listings across Apple, Garmin, and Samsung to uncover pricing dynamics, geographic arbitrage opportunities, and seller behavior patterns.</p>
    <p class="meta">Data Source: 3,607 resale listings (21 non-major-brand excluded) · Q1 2026 · 1,754 unique sellers across 27 countries</p>
  </div>
</header>

<div class="container">

<!-- KPI Dashboard -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="label">Median Price (Apple)</div>
    <div class="value">${kpi_brand_median['Apple']:,.0f}</div>
    <div class="context">Highest median resale value</div>
  </div>
  <div class="kpi-card">
    <div class="label">Geographic Price Spread</div>
    <div class="value">${geo_spreads['Apple']['spread']:,.0f}</div>
    <div class="context">Max arbitrage gap (Apple)</div>
  </div>
  <div class="kpi-card">
    <div class="label">Case Size Correlation</div>
    <div class="value">{cs_corr:+.3f}</div>
    <div class="context">Weak predictor of resale price</div>
  </div>
  <div class="kpi-card">
    <div class="label">Top 5% Seller Share</div>
    <div class="value">{concentration_pct}%</div>
    <div class="context">{n_top5pct} sellers control nearly half</div>
  </div>
  <div class="kpi-card">
    <div class="label">New vs Used Premium</div>
    <div class="value">{max(new_used_premium.values()):.0f}%</div>
    <div class="context">Samsung commands highest premium</div>
  </div>
</div>

<!-- SECTION 1: Market Overview -->
<div class="section">
  <h2><span class="section-num">1</span> Market Overview & Listing Composition</h2>
  <p class="objective">Summarize the overall dataset: total listings, brand distribution, condition mix, and geographic spread. Provide a high-level snapshot of the secondary smartwatch marketplace.</p>

  <div class="chart-row">
    <div class="chart-box">
      <h4>Brand Distribution</h4>
      <canvas id="chartBrandDist"></canvas>
    </div>
    <div class="chart-box">
      <h4>Condition Mix by Brand</h4>
      <canvas id="chartConditionStacked"></canvas>
    </div>
  </div>

  <div class="chart-row">
    <div class="chart-box">
      <h4>Top Countries by Listing Volume</h4>
      <canvas id="chartCountryVolume"></canvas>
    </div>
    <div class="chart-box">
      <h4>Worldwide Shipping Availability by Brand</h4>
      <canvas id="chartShipping"></canvas>
    </div>
  </div>

  <div class="insight">
    <strong>Key takeaway:</strong> Apple dominates the secondary market with 66.1% of all listings (2,370), followed by Garmin (20.8%, 746) and Samsung (13.1%, 470). The United States accounts for 65.3% of all listings (2,343). Garmin sellers offer worldwide shipping at 3x the rate of Apple sellers (47.5% vs 15.9%), reflecting Garmin's stronger international demand profile.
  </div>

  <table>
    <tr><th>Metric</th><th>Value</th></tr>
    <tr><td>Total Listings (main brands)</td><td>3,586</td></tr>
    <tr><td>Total Sellers</td><td>1,754</td></tr>
    <tr><td>Countries Represented</td><td>27</td></tr>
    <tr><td>Overall Median Price</td><td>$550.00</td></tr>
    <tr><td>Overall Mean Price</td><td>$617.82</td></tr>
    <tr><td>Price Range</td><td>$120.00 – $49,900.00</td></tr>
    <tr><td>Worldwide Shipping Rate</td><td>27.3%</td></tr>
    <tr><td>Case Size Data Available</td><td>75.7% of listings (2,724)</td></tr>
  </table>
</div>

<!-- SECTION 2: Brand-Level Pricing -->
<div class="section">
  <h2><span class="section-num">2</span> Brand-Level Pricing & Value Retention</h2>
  <p class="objective">Compare average, median, and price range across Apple, Garmin, and Samsung. Identify which brand commands the highest resale premiums and which shows the widest price variance.</p>

  <div class="chart-row">
    <div class="chart-box full">
      <h4>Price Distribution by Brand (Box Plot)</h4>
      <canvas id="chartBrandBox"></canvas>
    </div>
  </div>

  <div class="chart-row three">
    <div class="chart-box">
      <h4>Apple Price Distribution</h4>
      <canvas id="chartAppleDist"></canvas>
    </div>
    <div class="chart-box">
      <h4>Garmin Price Distribution</h4>
      <canvas id="chartGarminDist"></canvas>
    </div>
    <div class="chart-box">
      <h4>Samsung Price Distribution</h4>
      <canvas id="chartSamsungDist"></canvas>
    </div>
  </div>

  <div class="chart-row">
    <div class="chart-box full">
      <h4>New vs Used Price Premium by Brand</h4>
      <canvas id="chartNewUsedPremium"></canvas>
    </div>
  </div>

  <table>
    <tr><th>Brand</th><th>Listings</th><th>Mean</th><th>Median</th><th>P25</th><th>P75</th><th>IQR</th><th>Min</th><th>Max</th><th>New/Used Premium</th></tr>
    <tr>
      <td><strong>Apple</strong></td><td>2,370</td><td>$594.55</td><td><strong>$550.00</strong></td><td>$458.49</td><td>$669.99</td><td>$211.50</td><td>$120.00</td><td>$40,500.00</td><td>{new_used_premium.get('Apple', 0):.1f}%</td>
    </tr>
    <tr>
      <td><strong>Garmin</strong></td><td>746</td><td>$628.05</td><td><strong>$566.98</strong></td><td>$467.52</td><td>$749.99</td><td>$282.47</td><td>$215.10</td><td>$1,319.00</td><td>{new_used_premium.get('Garmin', 0):.1f}%</td>
    </tr>
    <tr>
      <td><strong>Samsung</strong></td><td>470</td><td>$725.49</td><td><strong>$530.00</strong></td><td>$449.96</td><td>$737.71</td><td>$287.75</td><td>$244.99</td><td>$49,900.00</td><td>{new_used_premium.get('Samsung', 0):.1f}%</td>
    </tr>
  </table>

  <div class="insight">
    <strong>Key takeaway:</strong> Garmin commands the highest median resale price ($566.98), reflecting strong value retention despite lower brand recognition than Apple. Samsung's mean ($725.49) is inflated by extreme high-end outliers in the UK market; its median ($530.00) reveals a more modest position. Apple anchors the market with the tightest interquartile range ($211.50), indicating a highly stable and predictable resale market — ideal for volume-based sourcing strategies.
  </div>

  <div class="insight green">
    <strong>Samsung's new-used premium anomaly (18.2%):</strong> Samsung's condition premium far exceeds Apple (8.2%) and Garmin (4.7%). This suggests Samsung buyers in the secondary market heavily discount used units, while new-in-box Samsung watches command near-retail prices. For operators, this means: source Samsung only new or open-box; avoid used Samsung inventory where margins erode.
  </div>
</div>

<!-- SECTION 3: Geographic Pricing Arbitrage -->
<div class="section">
  <h2><span class="section-num">3</span> Geographic Pricing Arbitrage</h2>
  <p class="objective">Analyze price differences by country for each brand. Highlight regions where specific brands are significantly cheaper or more expensive, identifying potential arbitrage opportunities.</p>

  <div class="geo-grid">
    <div class="geo-card">
      <h4>Apple Geographic Spread</h4>
      <div class="spread">${geo_spreads.get('Apple', {}).get('spread', 0):,.0f}</div>
      <div class="detail">
        Highest: {geo_spreads.get('Apple', {}).get('high', 'N/A')} — <strong>${geo_spreads.get('Apple', {}).get('high_val', 0):,.0f}</strong><br>
        Lowest: {geo_spreads.get('Apple', {}).get('low', 'N/A')} — <strong>${geo_spreads.get('Apple', {}).get('low_val', 0):,.0f}</strong><br>
        Potential margin: <strong>{round((geo_spreads.get('Apple', {}).get('spread', 0) / geo_spreads.get('Apple', {}).get('low_val', 1)) * 100, 1) if geo_spreads.get('Apple', {}).get('low_val', 0) > 0 else 0}%</strong> spread
      </div>
    </div>
    <div class="geo-card">
      <h4>Garmin Geographic Spread</h4>
      <div class="spread">${geo_spreads.get('Garmin', {}).get('spread', 0):,.0f}</div>
      <div class="detail">
        Highest: {geo_spreads.get('Garmin', {}).get('high', 'N/A')} — <strong>${geo_spreads.get('Garmin', {}).get('high_val', 0):,.0f}</strong><br>
        Lowest: {geo_spreads.get('Garmin', {}).get('low', 'N/A')} — <strong>${geo_spreads.get('Garmin', {}).get('low_val', 0):,.0f}</strong><br>
        Potential margin: <strong>{round((geo_spreads.get('Garmin', {}).get('spread', 0) / geo_spreads.get('Garmin', {}).get('low_val', 1)) * 100, 1) if geo_spreads.get('Garmin', {}).get('low_val', 0) > 0 else 0}%</strong> spread
      </div>
    </div>
    <div class="geo-card">
      <h4>Samsung Geographic Spread</h4>
      <div class="spread">${geo_spreads.get('Samsung', {}).get('spread', 0):,.0f}</div>
      <div class="detail">
        Highest: {geo_spreads.get('Samsung', {}).get('high', 'N/A')} — <strong>${geo_spreads.get('Samsung', {}).get('high_val', 0):,.0f}</strong><br>
        Lowest: {geo_spreads.get('Samsung', {}).get('low', 'N/A')} — <strong>${geo_spreads.get('Samsung', {}).get('low_val', 0):,.0f}</strong><br>
        Potential margin: <strong>{round((geo_spreads.get('Samsung', {}).get('spread', 0) / geo_spreads.get('Samsung', {}).get('low_val', 1)) * 100, 1) if geo_spreads.get('Samsung', {}).get('low_val', 0) > 0 else 0}%</strong> spread
      </div>
    </div>
  </div>

  <div class="chart-row">
    <div class="chart-box full">
      <h4>Country-Level Median Prices by Brand (Diverging from Global Median)</h4>
      <canvas id="chartGeoDiverging"></canvas>
    </div>
  </div>

  <div class="chart-row">
    <div class="chart-box full">
      <h4>Geographic Price Heatmap: Median Price by Country × Brand</h4>
      <canvas id="chartGeoHeatmap"></canvas>
    </div>
  </div>

  <div class="insight">
    <strong>Arbitrage opportunity #1 — UK Apple watches at a discount:</strong> Apple watches are priced 28.6% below the global Apple median in the United Kingdom ($392.74 vs $550.00). This is a structural discount — likely driven by high supply volume (214 listings) and localized market dynamics. Operators targeting the UK Apple market can acquire inventory at significant discounts and resell into higher-priced regions like Australia ($792 median) or Japan ($688 median).
  </div>

  <div class="insight green">
    <strong>Arbitrage opportunity #2 — Japan is the low-cost sourcing hub for Garmin & Samsung:</strong> Japan has the lowest median resale prices for both Garmin ($506.06) and Samsung ($437.32), making it a prime sourcing market for these brands. Combined with 87.5% of Japanese Garmin sellers offering worldwide shipping, the logistics are favorable for cross-border arbitrage.
  </div>

  <div class="insight amber">
    <strong>Arbitrage opportunity #3 — UK is the premium market for Garmin & Samsung:</strong> While the UK is cheap for Apple, it commands high premiums for Garmin ($775.00) and Samsung ($825.00). A cross-channel strategy — sourcing Apple in the UK and Garmin/Samsung in Japan, then reselling each into their respective premium markets — could yield double-digit margins. Samsung's spread in particular ($387.68, 88.6% gap) is the largest relative arbitrage opportunity in the dataset.
  </div>

  <table>
    <tr><th>Brand</th><th>Geographic Spread</th><th>Premium Market</th><th>Discount Market</th><th>Relative Gap</th></tr>
    <tr>
      <td>Apple</td><td>${geo_spreads.get('Apple', {}).get('spread', 0):,.0f}</td><td>{geo_spreads.get('Apple', {}).get('high', 'N/A')} (${geo_spreads.get('Apple', {}).get('high_val', 0):,.0f})</td><td>{geo_spreads.get('Apple', {}).get('low', 'N/A')} (${geo_spreads.get('Apple', {}).get('low_val', 0):,.0f})</td>
      <td>{round((geo_spreads.get('Apple', {}).get('spread', 0) / geo_spreads.get('Apple', {}).get('low_val', 1)) * 100, 1) if geo_spreads.get('Apple', {}).get('low_val', 0) > 0 else 0}%</td>
    </tr>
    <tr>
      <td>Garmin</td><td>${geo_spreads.get('Garmin', {}).get('spread', 0):,.0f}</td><td>{geo_spreads.get('Garmin', {}).get('high', 'N/A')} (${geo_spreads.get('Garmin', {}).get('high_val', 0):,.0f})</td><td>{geo_spreads.get('Garmin', {}).get('low', 'N/A')} (${geo_spreads.get('Garmin', {}).get('low_val', 0):,.0f})</td>
      <td>{round((geo_spreads.get('Garmin', {}).get('spread', 0) / geo_spreads.get('Garmin', {}).get('low_val', 1)) * 100, 1) if geo_spreads.get('Garmin', {}).get('low_val', 0) > 0 else 0}%</td>
    </tr>
    <tr>
      <td>Samsung</td><td>${geo_spreads.get('Samsung', {}).get('spread', 0):,.0f}</td><td>{geo_spreads.get('Samsung', {}).get('high', 'N/A')} (${geo_spreads.get('Samsung', {}).get('high_val', 0):,.0f})</td><td>{geo_spreads.get('Samsung', {}).get('low', 'N/A')} (${geo_spreads.get('Samsung', {}).get('low_val', 0):,.0f})</td>
      <td>{round((geo_spreads.get('Samsung', {}).get('spread', 0) / geo_spreads.get('Samsung', {}).get('low_val', 1)) * 100, 1) if geo_spreads.get('Samsung', {}).get('low_val', 0) > 0 else 0}%</td>
    </tr>
  </table>
</div>

<!-- SECTION 4: Case Size Premium -->
<div class="section">
  <h2><span class="section-num">4</span> Case Size & Price Premium Analysis</h2>
  <p class="objective">Examine the relationship between Case_Size_mm and listing price. Determine whether larger watch faces command a measurable premium and how this varies by brand.</p>

  <div class="chart-row">
    <div class="chart-box full">
      <h4>Median Price by Case Size Bin (by Brand)</h4>
      <canvas id="chartCaseSizePrice"></canvas>
    </div>
  </div>

  <table>
    <tr><th>Case Size Bin</th><th>Total Listings</th><th>Overall Median Price</th><th>Apple Median</th><th>Garmin Median</th><th>Samsung Median</th></tr>
    <tr><td>&lt;40mm</td><td>176</td><td>$496.50</td><td>$485.00</td><td>$735.00</td><td>$516.27</td></tr>
    <tr><td>40–43mm</td><td>406</td><td>$549.99</td><td>$529.99</td><td>$555.00</td><td>$645.00</td></tr>
    <tr><td>44–46mm</td><td>850</td><td>$503.27</td><td>$500.00</td><td>$549.99</td><td>$515.00</td></tr>
    <tr class="highlight"><td><strong>47–49mm</strong></td><td>1,218</td><td><strong>$592.32</strong></td><td>$589.99</td><td>$668.54</td><td>$549.00</td></tr>
    <tr class="highlight"><td><strong>50mm+</strong></td><td>74</td><td><strong>$630.23</strong></td><td>—</td><td>$630.23</td><td>—</td></tr>
  </table>

  <div class="insight">
    <strong>Key takeaway:</strong> The overall correlation between case size and resale price is negligible (<em>r</em> = {cs_corr:+.3f}), meaning case size alone is a poor predictor of listing price. However, a step-change premium emerges above 47mm: watches 47mm+ ($592–$630 median) command roughly 18–25% more than smaller sizes ($497–$550). This effect is most pronounced for Garmin, where the 50mm+ segment ($630 median) represents flagship adventure models (Fenix 7X, Epix Pro 51mm) that hold value through premium positioning rather than physical size per se.
  </div>

  <div class="insight green">
    <strong>Garmin is the outlier:</strong> Garmin (<em>r</em> = +0.107) shows the strongest case-size/price relationship among the three brands — more than 3x Apple's correlation (+0.033). This aligns with Garmin's product strategy of using larger cases for its premium multi-sport and dive watches. For sourcing: when buying Garmin inventory, prioritize 47mm+ models for higher resale value.
  </div>
</div>

<!-- SECTION 5: Power Seller Behavior -->
<div class="section">
  <h2><span class="section-num">5</span> Power Seller Behavior & Pricing Patterns</h2>
  <p class="objective">Identify high-volume sellers and compare their pricing strategies against low-volume sellers. Assess whether power sellers price higher or lower and whether they favor specific brands or conditions.</p>

  <div class="chart-row">
    <div class="chart-box">
      <h4>Seller Concentration: Top 5% vs Rest</h4>
      <canvas id="chartConcentration"></canvas>
    </div>
    <div class="chart-box">
