#!/usr/bin/env python3
"""Generate the Global Smartwatch Secondary Market Analysis Q1 2026 report."""

import pandas as pd
import numpy as np
import json
import os

# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
main_brands = ['Apple', 'Garmin', 'Samsung']
df_main = df[df['brand'].isin(main_brands)].copy()

# ── Normalize conditions (handle non-English labels) ───────────────────────
cond_map = {}
for c in df_main['condition'].unique():
    cl = str(c).lower()
    if 'new' in cl or 'nuevo' in cl or 'novo' in cl:
        cond_map[c] = 'New'
    elif 'used' in cl or 'usado' in cl:
        cond_map[c] = 'Used'
    elif 'open box' in cl or 'caja abierta' in cl:
        cond_map[c] = 'Open Box'
    elif 'refurbished' in cl:
        cond_map[c] = 'Refurbished'
    elif 'parts' in cl or 'not working' in cl:
        cond_map[c] = 'For Parts'
    else:
        cond_map[c] = c
df_main['cond_norm'] = df_main['condition'].map(cond_map)

# ── KPIs ───────────────────────────────────────────────────────────────────
kpi_brand_median = {}
for b in main_brands:
    kpi_brand_median[b] = round(df_main[df_main['brand'] == b]['price'].median(), 2)

# Geographic price spread
geo_spreads = {}
for b in main_brands:
    sub = df_main[df_main['brand'] == b]
    cm = sub.groupby('Country')['price'].agg(['median', 'count'])
    cm = cm[cm['count'] >= 5]
    if len(cm) > 1:
        geo_spreads[b] = {
            'spread': round(cm['median'].max() - cm['median'].min(), 2),
            'high': cm['median'].idxmax(),
            'high_val': round(cm['median'].max(), 2),
            'low': cm['median'].idxmin(),
            'low_val': round(cm['median'].min(), 2),
        }

# Case size correlation
valid_cs = df_main[df_main['Case_Size_mm'].notna()]
cs_corr = round(np.corrcoef(valid_cs['Case_Size_mm'].values, valid_cs['price'].values)[0, 1], 4)

# Power seller concentration
seller_counts = df_main['Seller_ID'].value_counts()
n_top5pct = max(1, int(len(seller_counts) * 0.05))
top_sellers = seller_counts.head(n_top5pct)
concentration_pct = round(top_sellers.sum() / len(df_main) * 100, 1)

# New vs Used price premium
new_used_premium = {}
for b in main_brands:
    sub = df_main[df_main['brand'] == b]
    new_avg = sub[sub['condition'] == 'New']['price'].mean()
    used_avg = sub[sub['condition'] == 'Used']['price'].mean()
    if used_avg > 0:
        new_used_premium[b] = round((new_avg - used_avg) / used_avg * 100, 1)

# ── Chart data helpers ─────────────────────────────────────────────────────
def chart_data_brand_pricing():
    """Box plot data for brand pricing."""
    datasets = []
    colors = {'Apple': 'rgba(102, 102, 102, 0.7)', 'Garmin': 'rgba(0, 163, 224, 0.7)', 'Samsung': 'rgba(20, 40, 120, 0.7)'}
    for b in main_brands:
        prices = df_main[df_main['brand'] == b]['price'].dropna().values.tolist()
        datasets.append({'label': b, 'data': prices, 'backgroundColor': colors[b]})
    return json.dumps(datasets)

def chart_data_brand_stats():
    """Mean/median/min/max for brand pricing."""
    result = []
    for b in main_brands:
        sub = df_main[df_main['brand'] == b]
        result.append({
            'brand': b,
            'mean': round(sub['price'].mean(), 2),
            'median': round(sub['price'].median(), 2),
            'p25': round(sub['price'].quantile(0.25), 2),
            'p75': round(sub['price'].quantile(0.75), 2),
            'min': round(sub['price'].min(), 2),
            'max': round(sub['price'].max(), 2),
        })
    return json.dumps(result)

def chart_data_geo_heatmap():
    """Country-level median prices by brand for heatmap/diverging bar."""
    result = {}
    for b in main_brands:
        sub = df_main[df_main['brand'] == b]
        cm = sub.groupby('Country')['price'].agg(['median', 'count'])
        cm = cm[cm['count'] >= 3].sort_values('median', ascending=False)
        result[b] = [{'country': idx, 'median': round(row['median'], 2), 'count': int(row['count'])} for idx, row in cm.iterrows()]
    return json.dumps(result)

def chart_data_case_size():
    """Case size bin data by brand."""
    bins = [0, 40, 43, 46, 49, 100]
    labels = ['<40mm', '40-43mm', '44-46mm', '47-49mm', '50mm+']
    result = []
    for b in main_brands:
        sub = valid_cs[valid_cs['brand'] == b].copy()
        sub['size_bin'] = pd.cut(sub['Case_Size_mm'], bins=bins, labels=labels)
        stats = sub.groupby('size_bin', observed=False)['price'].agg(['median', 'count'])
        result.append({
            'brand': b,
            'labels': labels,
            'medians': [float(round(stats.loc[l, 'median'], 2)) if l in stats.index and not pd.isna(stats.loc[l, 'median']) else None for l in labels],
            'counts': [int(stats.loc[l, 'count']) if l in stats.index else 0 for l in labels],
        })
    return json.dumps(result)

def chart_data_seller_scatter():
    """Seller volume vs median price."""
    seller_agg = df_main.groupby('Seller_ID').agg(
        listings=('price', 'count'),
        median_price=('price', 'median'),
        brand=('brand', lambda x: x.mode().iloc[0] if len(x) > 0 else 'Unknown')
    ).reset_index()
    return json.dumps(seller_agg[['listings', 'median_price', 'brand']].to_dict('records'))

def chart_data_condition_premium():
    """New vs Used prices by brand."""
    result = []
    for b in main_brands:
        sub = df_main[df_main['brand'] == b]
        for cond in ['New', 'Used', 'Open Box', 'Refurbished']:
            cs = sub[sub['cond_norm'] == cond]
            if len(cs) > 0:
                result.append({'brand': b, 'condition': cond, 'median': round(cs['price'].median(), 2), 'count': len(cs)})
    return json.dumps(result)

def chart_data_power_seller_pricing():
    """Power vs casual seller pricing by brand."""
    top_seller_ids = set(seller_counts.head(n_top5pct).index)
    df_main['seller_type'] = df_main['Seller_ID'].apply(lambda x: 'Power Seller' if x in top_seller_ids else 'Casual Seller')
    result = []
    for st in ['Power Seller', 'Casual Seller']:
        for b in main_brands:
            sub = df_main[(df_main['seller_type'] == st) & (df_main['brand'] == b)]
            if len(sub) > 0:
                result.append({'seller_type': st, 'brand': b, 'median': round(sub['price'].median(), 2), 'count': len(sub)})
    return json.dumps(result)

def chart_data_brand_distribution():
    """Brand + condition distribution for overview."""
    result = []
    for b in main_brands:
        for cond in ['New', 'Used', 'Open Box', 'Refurbished', 'For Parts']:
            cnt = len(df_main[(df_main['brand'] == b) & (df_main['cond_norm'] == cond)])
            if cnt > 0:
                result.append({'brand': b, 'condition': cond, 'count': cnt})
    return json.dumps(result)

def chart_data_country_distribution():
    """Top countries by listing volume."""
    country_counts = df_main['Country'].value_counts().head(12).reset_index()
    country_counts.columns = ['country', 'count']
    return json.dumps(country_counts.to_dict('records'))

def chart_data_shipping():
    """Worldwide shipping by brand."""
    result = []
    for b in main_brands:
        sub = df_main[df_main['brand'] == b]
        ww = int(sub['Is_Worldwide_Shipping'].sum())
        domestic = len(sub) - ww
        result.append({'brand': b, 'worldwide': ww, 'domestic': domestic})
    return json.dumps(result)

# ── Build HTML ─────────────────────────────────────────────────────────────
html = f'''<!DOCTYPE html>
